def pieces(g):
 cells={(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==8}
 out=[]
 for r in range(7):
  for c in range(7):
   sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
   if sq<=cells: out.append((sq,1))
   for offs,col in [({(0,0),(0,1),(1,1)},3),({(0,1),(1,0),(1,1)},2),({(0,0),(1,0),(1,1)},4),({(0,0),(0,1),(1,0)},5)]:
    sh={(r+a,c+b) for a,b in offs}
    if sh<=cells: out.append((sh,col))
 return cells,out
for idx,g in enumerate(examples):
 cells,ps=pieces(g)
 solutions=[]
 def dfs(rem,chosen):
  if not rem:
   solutions.append(chosen);return
  if len(solutions)>10000:return
  cell=min(rem)
  for sh,col in ps:
   if cell in sh and sh<=rem:
    dfs(rem-sh,chosen+[(sh,col)])
 dfs(cells,[])
 print(idx+1,'cells',len(cells),'solutions',len(solutions))
 if solutions:
  from collections import Counter
  print('solution color counts',Counter(tuple(sorted(Counter(c for _,c in sol).items())) for sol in solutions).most_common(5))

